def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, 18.0))

    urgent_prev = []
    rich_prev = []
    all_prev = []
    weak_count = 0
    desperate_count = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            all_prev.append(float(bid))
        opp_hp = opp.get('hp', 10)
        opp_nw = opp.get('no_water_days', 0)
        opp_budget = opp.get('budget', 0)
        if opp_hp <= 3 or opp_nw >= 1:
            desperate_count += 1
            if bid is not None:
                urgent_prev.append(float(bid))
        if opp_budget >= 140:
            weak_count += 0
        else:
            weak_count += 1
        if opp_budget >= 120 and bid is not None:
            rich_prev.append(float(bid))

    base = 22.0

    if supply <= 16:
        base = 52.0
    elif supply <= 18:
        base = 38.0
    elif supply >= 23:
        base = 18.0

    if hp <= 2 or no_water >= 2:
        base = max(base, 66.0)
    elif hp <= 4 or no_water >= 1:
        base = max(base, 48.0)

    if urgent_prev:
        top_urgent = max(urgent_prev)
        if hp <= 4 or no_water >= 1 or supply <= 18:
            base = max(base, min(72.0, top_urgent + 2.0))
        else:
            base = max(base, min(44.0, top_urgent * 0.72))

    if rich_prev:
        top_rich = max(rich_prev)
        if hp >= 6 and no_water == 0 and supply >= 19:
            base = min(base, 34.0)
        elif hp <= 3:
            base = max(base, min(78.0, top_rich * 0.55))

    if all_prev and desperate_count == 0 and supply >= 20:
        avg_prev = sum(all_prev) / float(len(all_prev))
        base = min(base, max(16.0, avg_prev * 0.35))

    if day >= 8:
        base += 6.0
    if day >= 9 and (hp <= 5 or no_water >= 1):
        base += 8.0

    if budget < 35:
        base = max(0.0, min(base, budget))
    else:
        reserve_floor = 10.0 if day >= 8 else 18.0
        base = min(base, max(0.0, budget - reserve_floor))

    if hp >= 8 and no_water == 0 and supply >= 22 and desperate_count == 0:
        base = min(base, 20.0)

    return float(max(0.0, min(budget, round(base, 2))))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents (only use current provided alive flag)
    alive_opps = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no opponents, take the safe minimum to meet requirement
    if not alive_opps:
        return int(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for o in alive_opps:
        pt = o.get('previous_trace', {})
        if isinstance(pt, dict):
            b = pt.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    # Estimate opponent pressure from yesterday
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Supply pressure: when supply is low, competition for the 9-water requirement is tighter
    # Approximate how many full requirements exist
    reqs = supply / float(WATER_REQ)
    scarcity = 0.0
    if reqs <= 1.2:
        scarcity = 1.0
    elif reqs <= 1.6:
        scarcity = 0.6
    elif reqs <= 2.2:
        scarcity = 0.3
    else:
        scarcity = 0.1

    # Our risk management
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # If we're already in danger, bid harder to avoid further no-water days
    if hp <= 2 or no_water_days >= 2:
        base = DAILY_SALARY * (0.85 + 0.1 * scarcity)
    elif hp <= 4:
        base = DAILY_SALARY * (0.65 + 0.15 * scarcity)
    else:
        base = DAILY_SALARY * (0.5 + 0.2 * scarcity)

    # If yesterday's highest bids were extreme, we slightly overbid but still cap to preserve budget
    # (Cindy/Eric were very high; Alex/David died, so avoid matching the very top unless needed.)
    if highest_prev_bid >= DAILY_SALARY * 1.4:
        # High pressure environment: move toward the 60-75% of top pressure
        opponent_anchor = min(highest_prev_bid * 0.62, DAILY_SALARY * 0.95)
        bid = max(base, opponent_anchor)
    elif highest_prev_bid >= DAILY_SALARY * 0.9:
        bid = max(base, avg_prev_bid * 0.85)
    else:
        # Moderate environment: aim above average a bit
        bid = max(base, avg_prev_bid * 0.75)

    # Budget and day scaling: earlier days bid a bit more; later days conserve
    day_factor = 1.0
    if day <= 3:
        day_factor = 1.05
    elif day >= 8:
        day_factor = 0.9

    bid = bid * day_factor

    # Final cap: never exceed what we can afford
    bid = min(bid, budget)

    # Ensure non-negative and integer
    if bid < 0:
        bid = 0

    return int(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid very low to save budget
    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Gather yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid considering urgency
    if my_hp <= 2 or no_water_days >= 1:
        urgency_multiplier = 0.9
    elif my_hp <= 4:
        urgency_multiplier = 0.7
    else:
        urgency_multiplier = 0.5

    base_bid = DAILY_SALARY * urgency_multiplier

    # Adjust based on yesterday's highest bid (if any)
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        # If opponents were aggressive, we might need to match or exceed
        if highest_prev > DAILY_SALARY * 0.8:
            # Opponents aggressive; if we can afford, bid slightly above their max
            if my_hp <= 3:
                target = min(highest_prev + 2, my_budget)
            else:
                target = min(highest_prev * 0.85, my_budget)
        else:
            # Opponents moderate; we can outbid them by small margin
            target = min(max(base_bid, highest_prev + 1.5), my_budget)
    else:
        target = min(base_bid, my_budget)

    # Ensure we don't bid more than we can afford and at least 0
    bid = max(0.0, target)
    return bid
